def formula_value(formula):
    s = formula.replace(' ', '')
    stack = []  # frames: (name, arguments so far)
    value = None
    i, n = 0, len(s)
    while i < n:
        c = s[i]
        if c.isalpha():
            j = s.index('(', i)
            stack.append((s[i:j], []))
            i = j + 1
            continue
        if c == ',':
            i += 1
            continue
        if c == ')':
            name, args = stack.pop()
            v = sum(args) if name == 'SUM' else max(args) if name == 'MAX' else min(args)
            i += 1
        else:
            j = i + 1
            while j < n and s[j].isdigit():
                j += 1
            v = int(s[i:j])
            i = j
        if stack:
            stack[-1][1].append(v)
        else:
            value = v
    return value

